#include <bits/stdc++.h>
#define BIG_INF 17446744073709551616ULL
#define ULL unsigned long long
using namespace std;

ULL M, nVal, kVal, dpArr[19][300005];
ULL fact[300005], invFact[300005];

ULL power(ULL base, ULL exp) {
    ULL res = 1ULL;
    while (exp > 0) {
        if (exp & 1ULL) res = (res * base) % M;
        base = (base * base) % M;
        exp >>= 1ULL;
    }
    return res;
}

ULL nChoose(int a, int b) {
    return (((fact[a] * invFact[b]) % M) * invFact[a - b]) % M;
}

ULL computeResult() {
    int i, j, mask;
    fact[0] = 1ULL;
    ULL limit = max(nVal, kVal);
    for (i = 1; i <= limit; i++) {
        fact[i] = (fact[i - 1] * (ULL)i) % M;
    }
    invFact[limit] = power(fact[limit], M - 2ULL);
    for (i = limit - 1; i >= 0; i--) {
        invFact[i] = (invFact[i + 1] * (ULL)(i + 1)) % M;
    }
    for (i = 1; i <= nVal; i++) {
        dpArr[1][i] = invFact[i];
    }
    ULL totalAns = dpArr[1][nVal] * nChoose(kVal, 1) % M;
    int maxIter = min(18, (int)kVal);
    for (i = 2; i <= maxIter; i++) {
        for (j = nVal; j > 0; j = (j - 1) & nVal) {
            if (!dpArr[i - 1][j]) continue;
            int rem = nVal ^ j;
            for (mask = rem; mask > j; mask = (mask - 1) & rem) {
                dpArr[i][j ^ mask] += dpArr[i - 1][j] * invFact[mask];
                if (dpArr[i][j ^ mask] > BIG_INF) dpArr[i][j ^ mask] %= M;
            }
        }
        for (j = nVal; j > 0; j = (j - 1) & nVal) {
            if (dpArr[i][j] >= M) dpArr[i][j] %= M;
        }
        ULL resVal = dpArr[i][nVal] * nChoose(kVal, i) % M;
        resVal = (resVal * fact[i]) % M;
        totalAns = (totalAns + resVal >= M ? totalAns + resVal - M : totalAns + resVal);
    }
    totalAns = (totalAns * fact[nVal]) % M;
    return totalAns;
}

int main() {
    cin >> nVal >> kVal >> M;
    ULL ans = power(kVal, nVal);
    if (nVal % 2 == 0) ans = (ans - computeResult() + M) % M;
    cout << ans << endl;
    return 0;
}
